$('#save-demo').addEventListener('click',e=>{const b=e.currentTarget,saved=b.getAttribute('aria-pressed')!=='true';b.setAttribute('aria-pressed',String(saved));b.setAttribute('aria-label',saved?'Remover dos salvos':'Salvar exemplo');b.textContent=saved?'★':'☆';$('#demo-output').textContent=saved?'Exemplo salvo nesta sessão.':'Exemplo removido dos salvos.'});
let flows=[{name:'Resumo diário de vendas',area:'Comercial',active:true},{name:'Triagem de atendimento',area:'Atendimento',active:true},{name:'Conciliação de dados',area:'Operações',active:false}];
function renderFlows(){const query=$('#flow-search').value.toLocaleLowerCase('pt-BR');const list=$('#flow-list');list.replaceChildren();flows.forEach((f,i)=>{if(!`${f.name} ${f.area}`.toLocaleLowerCase('pt-BR').includes(query))return;const row=document.createElement('div');row.className='flow';const text=document.createElement('div'),name=document.createElement('strong'),area=document.createElement('small'),button=document.createElement('button');name.textContent=f.name;area.textContent=`${f.area} / Fluxo demonstrativo`;text.append(name,area);button.textContent=f.active?'● Ativo':'Pausado';button.setAttribute('aria-pressed',String(f.active));button.setAttribute('aria-label',`${f.active?'Pausar':'Ativar'} ${f.name}`);button.addEventListener('click',()=>{flows[i].active=!f.active;renderFlows();toast(`${f.name}: ${flows[i].active?'ativado':'pausado'}`)});row.append(text,button);list.append(row)});if(!list.children.length){const p=document.createElement('p');p.className='empty';p.textContent='Nenhum fluxo encontrado. Experimente outra busca.';list.append(p)}}renderFlows();
$('#flow-search').addEventListener('input',renderFlows);
$('#demo-form').addEventListener('submit',e=>{e.preventDefault();const name=$('#flow-name').value.trim();if(!name){$('#flow-name').setCustomValidity('Digite um nome para o fluxo.');$('#flow-name').reportValidity();return}flows.unshift({name,area:$('#flow-category').value,active:true});$('#flow-search').value='';renderFlows();$('#form-result').textContent=`“${name}” criado na demonstração.`;$('#flow-name').value='';toast('Fluxo de demonstração criado')});
$('#flow-name').addEventListener('input',()=>$('#flow-name').setCustomValidity(''));
$('#reset-demo').addEventListener('click',()=>{flows=[{name:'Resumo diário de vendas',area:'Comercial',active:true},{name:'Triagem de atendimento',area:'Atendimento',active:true},{name:'Conciliação de dados',area:'Operações',active:false}];$('#flow-search').value='';$('#demo-form').reset();$('#form-result').textContent='Crie um fluxo de demonstração.';$('#save-demo').setAttribute('aria-pressed','false');$('#save-demo').setAttribute('aria-label','Salvar exemplo');$('#save-demo').textContent='☆';$('#demo-output').textContent='Demonstração reiniciada.';renderFlows();toast('Exemplo reiniciado')});
$('#metric-period').addEventListener('change',e=>{const week=e.target.value==='week';$('#metric-value').innerHTML=week?'32<span>h</span>':'128<span>h</span>';$('#metric-change').textContent=week?'↑ 12% em relação à semana anterior':'↑ 18% em relação ao mês anterior';$$('.chart i').forEach((bar,i)=>bar.style.setProperty('--h',`${(week?[45,30,64,55,78,67,90]:[30,48,42,64,56,82,96])[i]}%`))});
