const lightbox=$('#lightbox');let lightboxTrigger;function closeLightbox(){lightbox.close();document.body.style.overflow='';lightboxTrigger?.focus()}
$$('[data-image]').forEach(b=>b.addEventListener('click',()=>{lightboxTrigger=b;$('img',lightbox).src=b.dataset.image;$('img',lightbox).alt=$('img',b).alt;$('#lightbox-title').textContent=b.dataset.title;lightbox.showModal();document.body.style.overflow='hidden'}));$('.lightbox-close').addEventListener('click',closeLightbox);lightbox.addEventListener('cancel',e=>{e.preventDefault();closeLightbox()});lightbox.addEventListener('click',e=>{if(e.target===lightbox)closeLightbox()});
const reduced=matchMedia('(prefers-reduced-motion: reduce)');
const meshObserver=new IntersectionObserver(entries=>entries.forEach(entry=>entry.target.classList.toggle('in-view',entry.isIntersecting)));$$('.mesh').forEach(el=>meshObserver.observe(el));
if(!reduced.matches){const observer=new IntersectionObserver(entries=>entries.forEach(entry=>{if(entry.isIntersecting){entry.target.classList.add('visible');observer.unobserve(entry.target)}}),{threshold:.08});$$('.chapter h2,.statement h3,.trait,.logo-stage>img,.social-post h3,.mockup').forEach(el=>{el.classList.add('reveal');observer.observe(el)});const words=$('.word-reveal');words.innerHTML=words.textContent.split(' ').map(w=>`<span>${w}</span>`).join(' ');words.classList.add('is-animated')}
const sections=$$('.spread[id],#ui-kit,#botoes,#campos'),links=$$('#menu-links a');let ticking=false;
function onScroll(){const max=document.documentElement.scrollHeight-innerHeight;$('.progress').style.width=`${max>0?scrollY/max*100:0}%`;let active='';for(const section of sections)if(section.getBoundingClientRect().top<innerHeight*.45)active=section.id;links.forEach(link=>{if(link.hash===`#${active}`)link.setAttribute('aria-current','location');else link.removeAttribute('aria-current')});if(!reduced.matches){const words=$('.word-reveal'),rect=words.getBoundingClientRect(),amount=Math.max(0,Math.min(1,(innerHeight*.88-rect.top)/(rect.height+innerHeight*.25)));$$('span',words).forEach((span,i,all)=>span.classList.toggle('read',i/all.length<=amount))}ticking=false}
addEventListener('scroll',()=>{if(!ticking){requestAnimationFrame(onScroll);ticking=true}},{passive:true});addEventListener('resize',onScroll);onScroll();


